eam_id]`" x-model="pick.team_id" required><option value="">Select team</option>@foreach ($tournament->teams as $team)<option value="{{ $team->id }}">{{ $team->name }}</option>@endforeach</select></td><td><div class="input-group"><input type="number" min="5" max="3600" class="form-control" :name="`rounds[${roundIndex}][picks][${pickIndex}][pick_duration]`" x-model.number="pick.pick_duration" required><span class="input-group-text bg-light">sec</span></div></td><td class="text-end"><button type="button" class="btn btn-sm btn-light text-danger" @click="removePick(roundIndex, pickIndex)" :disabled="round.picks.length === 1" aria-label="Remove pick"><i class="fa-solid fa-trash"></i></button></td></tr></template></tbody></table></div></div></template>
