    <script>
        function draftSetupForm() { const existing = @js($draft->rounds->map(fn ($round) => ['key' => 'round-'.$round->id, 'round_number' => $round->round_number, 'name' => $round->name, 'picks' => $round->picks->map(fn ($pick) => ['key' => 'pick-'.$pick->id, 'pick_number' => $pick->pick_number, 'team_id' => (string) $pick->team_id, 'pick_duration' => $pick->pick_duration])->values()])->values()); return { nextKey: 1, rounds: existing.length ? existing : [{ key: 'round-new-0', round_number: 1, name: 'Round 1', picks: [{ key: 'pick-new-0', pick_number: 1, team_id: '', pick_duration: {{ $tournament->default_pick_duration }} }] }], addRound() { const number = this.rounds.length + 1; this.rounds.push({ key: `round-new-${this.nextKey++}`, round_number: number, name: `Round ${number}`, picks: [{ key: `pick-new-${this.nextKey++}`, pick_number: this.nextPickNumber(), team_id: '', pick_duration: {{ $tournament->default_pick_duration }} }] }); }, removeRound(index) { if (this.rounds.length > 1) this.rounds.splice(index, 1); }, addPick(roundIndex) { this.rounds[roundIndex].picks.push({ key: `pick-new-${this.nextKey++}`, pick_number: this.nextPickNumber(), team_id: '', pick_duration: {{ $tournament->default_pick_duration }} }); }, removePick(roundIndex, pickIndex) { if (this.rounds[roundIndex].picks.length > 1) this.rounds[roundIndex].picks.splice(pickIndex, 1); }, nextPickNumber() { return this.rounds.reduce((max, round) => Math.max(max, ...round.picks.map(pick => Number(pick.pick_number) || 0)), 0) + 1; } }; }
    </script>
